import {ArrowUpRight,ArrowRight,Plus,Search,ChevronDown,ChevronLeft,ChevronRight,LayoutDashboard,Users,Compass,CalendarDays,Lightbulb,FileText,Palette,CheckCheck,Send,ChartNoAxesCombined,Globe,ScanSearch,Megaphone,Handshake,BriefcaseBusiness,Settings,LogOut,Bell,Command,MoreHorizontal,Check,Clock,Loader2,X,Download,Upload,Link2,ShieldCheck,Layers,Activity,Play,Sparkles,AlertCircle,Copy,ExternalLink,Lock,FolderOpen,RefreshCw,CheckCircle2,Menu,ArrowLeft,Trash2,MessageCircle,Mic} from 'lucide-react';
import AgentChat from './AgentChat';
