const newRecord=(kind:string)=>{const defaults:any={BrandKit:{colors:['#244c3b','#d9edaf'],font:'Arial',voice:'',audience:'',banned_words:[],disclaimers:''},Strategy:{body:'',positioning:'',objective:'',audience:''},Campaign:{budget:30000,month,objective:'',channels:[],slots:[]},Asset:{type:'copy',format:'Reel',language:'English',script:'',caption:'',cta:'',on_screen_text:[]},Metric:{source:'Manual',metric:'leads',value:0,date:new Date().toISOString().slice(0,10),label:'real'},Learning:{body:'',industry:client?.industry,objective:'',pattern:'',evidence_links:[]},Task:{owner:data?.user?.name,due_date:new Date().toISOString().slice(0,10),module:'managing',priority:'medium',body:''},Report:{body:'',period:''}};edit({kind,title:'',data:defaults[kind]||{body:''}})};
